@@ -0,0 +1,10 @@
+{#- The /app/ stand-in (#1103): what a visitor sees there when the site was built without the browser build. On a release the workflow replaces this folder with the app itself. Provenance: our own template. -#}
+{% extends "base.html" %}
+{% block title %}{{ page.title }} - {{ config.title }}{% endblock title %}
+{% block description %}{{ page.description }}{% endblock description %}
+{% block content %}
+<article class="doc">
+  <h1>{{ page.title }}</h1>
+  {{ page.content | safe }}
+</article>
+{% endblock content %}

